        exhaustIds: ec.exhaust_fan_entities ?? [],
        circulationIds: ec.circulation_fan_entities ?? [],
        humidifierIds: ec.humidifier_entities ?? [],
        dehumidifierIds: ec.dehumidifier_entities ?? [],
